SELECT id, companyName, userId, contactEmail FROM sponsors WHERE companyName LIKE '%Bright%';

-- Find Kristen's user account
SELECT id, name, email, role, createdAt FROM users WHERE name LIKE '%Kristen%' OR name LIKE '%kristen%' OR email LIKE '%kristen%' OR email LIKE '%bright%';

